/** Pure alias identity for save validation; eligibility is checked by the engine separately. */
export function caseActionId(action:CaseAction,age:number,clubId:string|null,category:string):string {
  const talk=!!clubId&&age>=16;
  if(action==='path')return age<=18?'career:education':category==='SENIOR'?'career:market':talk?'career:discuss':'routine:review';
  if(action==='stable')return category==='SENIOR'?'career:stable':'career:local';
  if(action==='discuss')return talk?'career:discuss':'routine:review';
  if(action==='food')return age>=18?'routine:pizza-beer':'routine:food';
  if(action==='night')return age>=18?'routine:party':'routine:gaming';
  return `routine:${action}`;
}
